'use strict';
const root = document.getElementById('root');
const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const deliveryText = t => t==='均可'?'自提 / 邮寄':t;
const money = n => Number(n).toLocaleString('zh-CN', { maximumFractionDigits: 2 });
const categories = [['compass','全部'],['chair','家居生活'],['camera','数码家电'],['shirt','服饰鞋包'],['book','图书文具']];
const mainScreens = ['home','discover','publish','messages','profile'];
const urlParams = new URLSearchParams(location.search);
let route = { screen: urlParams.get('screen') || 'home', item: urlParams.get('item') || 'chair-01', category: urlParams.get('category') || '全部', query: urlParams.get('query') || '', order: urlParams.get('order') || '', seller: urlParams.get('seller') || '' };
for(const key of ['post','mode','select','address','return','edit'])if(urlParams.has(key))route[key]=urlParams.get(key);
let checkoutDrafts={};
let backStack = [], searchSort = '综合', filters = {}, homeFeed = '推荐', orderFilter = '全部', messageFilter='全部', discoverFeed='推荐';
let accountForm = { phone:'', password:'', code:'', consent:false }, accountError='', accountBusy=false, smsUntil=0, timer;
let pendingRoute=null, paymentMethod='微信支付', publishedId='', selectedDelivery='', selectedAddress='', newDraftPhotos=[], draftEditingId='', reviewMode = urlParams.has('review') || urlParams.has('board');
const screenScroll = new Map();

function attrs(data){return Object.entries(data).filter(([,v])=>v!==undefined&&v!=='').map(([k,v])=>` data-${k}="${esc(v)}"`).join('')}
function navButton(label, screen, cls='', data={}) {return `<button type="button" class="${cls}" data-go="${screen}"${label.replace(/<[^>]*>/g,'').trim()?'':` aria-label="${esc(({search:'搜索',settings:'设置',seller:'查看卖家'})[screen]||screen)}"`}${attrs(data)}>${label}</button>`}
function action(label, name, cls='', data={}) {return `<button type="button" class="${cls}" data-action="${name}"${data.label?` aria-label="${esc(data.label)}"`:""}${attrs(data)}>${label}</button>`}
function primary(label, screen, data={}) {return navButton(label,screen,'btn primary',data)}
function avatar(seller, large=false){let s=typeof seller==='string'?WY.seller(seller):seller;if(!s)s={name:'用户',initial:'友'};return s.avatar?`<img class="avatar${large?' large':''}" src="${esc(s.avatar)}" alt="${esc(s.name)}">`:`<span class="avatar${large?' large':''}">${esc(s.initial||s.name?.slice(0,1)||'友')}</span>`}
function timeAgo(ms){let days=Math.floor((Date.now()-Number(ms))/86400000);return days<1?'今天':days===1?'昨天':days<7?`${days} 天前`:'一周前'}
function currentProduct(){return WY.product(route.item)||WY.products()[0]}
function currentOrder(){return route.order?WY.order(route.order):WY.state.orders[0]}
function currentSeller(){return WY.seller(route.seller||currentProduct().sellerId)}
function backButton(){return `<button class="icon-button nav-back" data-action="back" aria-label="返回">${icon('back')}</button>`}
function header(title, right='', noBack=false){return `<header class="app-header">${noBack?'':backButton()}${title?`<h1 class="header-title">${esc(title)}</h1>`:'<span class="header-title"></span>'}${right||'<span class="header-spacer"></span>'}</header>`}
function tabs(active){let unread=Object.values(WY.state.conversations).filter(c=>c.unread>0).length;return `<nav class="tabbar" aria-label="底部导航">${[['home','home','首页'],['discover','compass','逛逛'],['publish','plus','发布'],['messages','chat','消息'],['profile','user','我的']].map(([id,i,t])=>`<button class="tab ${id===active?'active':''} ${id==='publish'?'publish-tab':''}" data-go="${id}"${id===active?' aria-current="page"':''}><span class="tab-icon">${icon(i,id==='publish'?26:23)}${id==='messages'&&unread?'<i class="nav-dot"></i>':''}</span><span>${t}</span></button>`).join('')}</nav>`}
function frame(body, {title='',right='',tab='',footer='',headerHTML='',noBack=false}={}){return `<div class="app" data-screen="${esc(route.screen)}">${headerHTML||header(title,right,noBack)}<main class="screen-body" id="screen-body">${body}</main>${footer?`<footer class="app-footer">${footer}</footer>`:''}${tab&&tab!=='publish'?tabs(tab):''}<div id="overlay-root"></div><div id="toast-root" aria-live="polite"></div></div>`}
function heading(text,more='',to='',data={}){return `<div class="section-heading"><h2>${esc(text)}</h2>${more?navButton(esc(more)+icon('next',15),to,'text-button',data):''}</div>`}
function empty(title,copy,link='去逛逛',to='home',name='bag'){return `<div class="empty-state"><div class="empty-icon">${icon(name,46)}</div><h2 class="empty-title">${esc(title)}</h2><p class="empty-copy">${esc(copy)}</p>${link?navButton(esc(link),to,'btn primary compact'):''}</div>`}
function productCard(p, nearby=false){const s=WY.seller(p.sellerId),favorite=WY.isFavorite(p.id);return `<article class="product-card" data-product="${esc(p.id)}"><button class="product-open" data-go="detail" data-item="${esc(p.id)}"><div class="product-image-wrap"><img class="product-image" src="${esc(p.photos[0])}" alt="${esc(p.title)}" loading="lazy"></div><div class="product-info"><h3 class="product-title">${esc(p.title)}</h3><div class="product-meta">${esc(p.condition)}<span>·</span>${nearby?esc(p.distance+' km'):esc(p.district||p.city)}</div><div class="row between product-price-row"><strong class="product-price"><span class="currency">¥</span>${money(p.price)}</strong><span class="count-text">${p.wants||0}人想要</span></div><div class="seller-line">${avatar(s)}<span>${esc(s.name)}</span></div></div></button><button class="favorite-button ${favorite?'is-favorite':''}" data-action="favorite" data-item="${esc(p.id)}" aria-label="${favorite?'取消收藏':'收藏'}${esc(p.title)}" aria-pressed="${favorite}">${icon('heart',19)}</button></article>`}
function productGrid(items,nearby=false){return items.length?`<div class="product-grid">${items.map(p=>productCard(p,nearby)).join('')}</div>`:`<div class="empty-state"><div class="empty-icon">${icon('search',40)}</div><h2 class="empty-title">暂时没有匹配的好物</h2><p class="empty-copy">换个关键词，或者调整一下筛选条件。</p>${Object.keys(filters).length?action('清除筛选','clear-filters','btn secondary compact'):navButton('重新搜索',route.screen==='results'?'search':'home','btn secondary compact',{query:route.query||''})}</div>`}
function listRow(title,i,to,trail='',data={}){return navButton(`<span class="list-leading">${icon(i,21)}<span>${esc(title)}</span></span><span class="list-trailing">${esc(trail)}${icon('next',17)}</span>`,to,'list-row',data)}
function formField(label,name,placeholder,type='text',value='',extra=''){return `<div class="field"><label class="field-label" for="field-${name}">${esc(label)}</label><div class="input-shell"><input class="input-control" id="field-${name}" name="${name}" aria-label="${esc(label)}" type="${type}" placeholder="${esc(placeholder)}" value="${esc(value)}" ${extra}>${type==='password'?action(icon('eye',20),'eye','icon-button password-toggle',{'label':'显示密码'}):''}</div><p class="field-error" data-error-for="${name}"></p></div>`}
function thumbRow(p){return `<div class="order-product"><img class="order-image" src="${esc(p.photos[0])}" alt="${esc(p.title)}"><div class="order-product-main"><h3 class="order-title">${esc(p.title)}</h3><p class="muted small">${esc(p.condition)} · ${esc(deliveryText(p.delivery))}</p><strong class="inline-price">¥${money(p.price)}</strong></div></div>`}

function home(){let productItems=WY.search({sort:homeFeed==='最新'?'最新':'综合',nearby:homeFeed==='附近'}).filter(p=>p.sellerId!=='me');if(homeFeed==='百元内')productItems=productItems.filter(p=>p.price<=100);return frame(`<div class="page-pad home-page">${navButton(icon('search',21)+'<span>搜索你想要的好物</span>','search','home-search')}<button class="hero-banner" data-go="topic"><img class="hero-photo" src="assets/v2/hero-wide.jpg" alt="自然光里的客厅"><span class="hero-copy"><strong class="hero-title">把喜欢，<br>带回家。</strong><span class="hero-subtitle">发现值得再被珍惜的好物</span><span class="hero-link">逛逛家居 ${icon('arrow',17)}</span></span></button><div class="category-grid">${categories.slice(1).concat([['compass','全部分类']]).map(([i,c])=>navButton(`<span class="category-icon">${icon(i,24)}</span><span>${c}</span>`,c==='全部分类'?'categories':'category','category-button',{category:c})).join('')}</div><div class="segmented home-segmented">${['推荐','最新','附近','百元内'].map(t=>action(t,'home-feed',`segmented-button ${homeFeed===t?'active':''}`,{value:t})).join('')}</div>${productGrid(productItems,homeFeed==='附近')}</div>`,{headerHTML:`<header class="app-header home-header"><div class="brand-lockup">${logo(34)}<span class="brand-name">闲置无忧</span></div>${navButton(icon('pin',17)+`<span>${esc(WY.state.city)}</span>`+icon('next',14),'location','location-button')}</header>`,tab:'home'})}
function categoriesPage(){return frame(`<div class="page-pad"><div class="category-list">${categories.slice(1).map(([i,c])=>navButton(`<span class="category-icon">${icon(i,26)}</span><span>${c}</span><span class="list-trailing">${WY.search({category:c}).length} 件好物 ${icon('next',17)}</span>`,'category','list-row',{category:c})).join('')}</div></div>`,{title:'全部分类'})}
function searchPage(){let histories=[];try{histories=JSON.parse(localStorage.getItem('xzw-v2-searches')||'[]')}catch{}return frame(`<div class="page-pad"><form class="search-form" id="search-form"><div class="search-input">${icon('search',21)}<input name="query" aria-label="搜索关键词" placeholder="物品名称、品牌或型号" value="${esc(route.query)}" autofocus autocomplete="off"></div><button class="text-button" type="submit">搜索</button></form>${histories.length?`<div class="section-heading"><h2>最近搜索</h2>${action('清除','clear-search','text-button')}</div><div class="search-terms">${histories.map(t=>navButton(esc(t),'results','search-term',{query:t})).join('')}</div>`:''}${heading('热门搜索')}<div class="popular-searches">${['休闲椅','相机','键盘','盆栽','双肩包','台灯'].map((t,i)=>navButton(`<span class="muted">${i+1}</span><span>${t}</span>`,'results','popular-search',{query:t})).join('')}</div></div>`,{title:'搜索'})}
function results(){let category=route.screen==='category'?route.category:'全部',nearby=route.screen==='nearby';let list=WY.search({...filters,query:route.query,category,sort:searchSort,nearby});if(route.query){let histories=[];try{histories=JSON.parse(localStorage.getItem('xzw-v2-searches')||'[]')}catch{}localStorage.setItem('xzw-v2-searches',JSON.stringify([route.query,...histories.filter(x=>x!==route.query)].slice(0,8)))}let title=nearby?'附近好物':route.screen==='category'?category:'搜索结果';return frame(`<div class="page-pad">${route.screen==='results'?navButton(icon('search',20)+`<span>${esc(route.query||'搜索好物')}</span>`,'search','home-search',{query:route.query}):''}<div class="filter-bar">${['综合','最新','价格'].map(t=>action(t+(t==='价格'?icon('arrow',13):''),'sort',`filter-button ${searchSort===t?'active':''}`,{value:t})).join('')}${action('筛选 '+icon('filter',17),'filters',`filter-button ${Object.keys(filters).length?'active':''}`)}</div><div class="result-count">${nearby?esc(WY.state.city)+' · ':''}${list.length} 件好物${Object.keys(filters).length&&list.length?action('清除条件','clear-filters','text-button'):''}</div>${productGrid(list,nearby)}</div>`,{title,right:navButton(icon('search'),'search','icon-button')})}
function detail(){let p=currentProduct(),s=WY.seller(p.sellerId),f=WY.isFavorite(p.id),existingOrder=WY.state.orders.find(o=>o.productId===p.id&&o.status!=='已取消');return frame(`<div class="detail-gallery"><img class="detail-photo" src="${esc(p.photos[0])}" alt="${esc(p.title)}">${p.photos.length>1?`<div class="photo-count">1 / ${p.photos.length}</div>`:''}</div><div class="page-pad detail-info"><div class="row between"><div class="detail-price">¥${money(p.price)}${p.originalPrice?`<s>¥${money(p.originalPrice)}</s>`:''}</div><span class="muted small">${p.wants}人想要</span></div><h2 class="detail-title">${esc(p.title)}</h2><p class="detail-summary">${esc(p.condition)} · ${esc(p.city)}${esc(p.district)} · ${esc(deliveryText(p.delivery))}</p><div class="divider"></div>${navButton(`${avatar(s)}<span class="seller-block-main"><strong>${esc(s.name)}</strong><span class="muted small">${esc(s.lastActive||'今天来过')} · ${esc(s.city)}</span></span>${icon('next',18)}`,'seller','seller-block',{seller:s.id})}<div class="divider"></div><h3 class="page-heading">物品描述</h3><p class="detail-description">${esc(p.description)}</p><div class="attribute-grid"><div class="attribute"><span>分类</span><strong>${esc(p.category)}</strong></div><div class="attribute"><span>成色</span><strong>${esc(p.condition)}</strong></div><div class="attribute"><span>交易方式</span><strong>${esc(deliveryText(p.delivery))}</strong></div></div><p class="safety-note">${icon('shield',17)}请在平台内沟通，收货后再确认完成。</p></div>`,{title:'商品详情',right:action(icon('heart',22),'favorite',`icon-button ${f?'is-favorite':''}`,{item:p.id}),footer:`<div class="action-bar">${navButton('聊一聊','chat','btn secondary',{item:p.id})}${navButton(p.sellerId==='me'?'编辑商品':existingOrder?'查看订单':'我想要',p.sellerId==='me'?'publish':existingOrder?'order-detail':'checkout','btn primary',{item:p.id,...(existingOrder?{order:existingOrder.id}:{})})}</div>`})}
function discover(){let posts=[{id:'room',title:'不用买全新的，也能住进喜欢的家',text:'一把舒服的椅子，一盏暖光灯。慢慢添置，房间就有了自己的样子。',img:'assets/v2/hero-wide.jpg',seller:'mumu',item:'chair-01'},{id:'plant',title:'给窗台添一点绿，只需要一盆多肉',text:'从附近邻居手里接过这盆小植物，连花盆一起，刚好放在窗边。',img:'assets/v2/plant-potted.jpg',seller:'manman',item:'plant-01'}];return frame(`<div class="page-pad"><div class="segmented">${['推荐','关注'].map(t=>action(t,'discover-feed',`segmented-button ${discoverFeed===t?'active':''}`,{value:t})).join('')}</div>${(discoverFeed==='关注'?posts.filter(p=>WY.state.followed.includes(normalSeller(p.seller))):posts).map(p=>postCard(p)).join('')||(empty('还没有关注的动态','关注喜欢的分享者，看看他们最近的生活。','发现更多','discover','compass'))}</div>`,{title:'逛逛',noBack:true,right:navButton(icon('search'),'search','icon-button'),tab:'discover'})}
function normalSeller(id){return WY.seller(id)?.id || WY.products().find(p=>p.id==='chair-01')?.sellerId}
function postCard(post){let seller=WY.seller(normalSeller(post.seller));return `<article class="post-card">${navButton(`<img class="post-cover" src="${post.img}" alt="${esc(post.title)}">`,'post','post-open',{post:post.id,item:post.item})}<div class="post-card-body">${navButton(`<h2 class="post-title">${post.title}</h2><p class="post-excerpt">${post.text}</p>`,'post','post-open',{post:post.id,item:post.item})}<div class="post-actions"><div class="post-author">${avatar(seller)}<span>${esc(seller.name)}</span></div>${action(icon('heart',18)+' <span>'+ (WY.state.likes.includes(post.id)?'129':'128')+'</span>','like',`text-button ${WY.state.likes.includes(post.id)?'is-favorite':''}`,{post:post.id})}</div></div></article>`}
function post(){let plant=route.post==='plant',sid=normalSeller(plant?'manman':'mumu'),s=WY.seller(sid),pid=plant?'plant-01':'chair-01',p=WY.product(pid)||currentProduct();return frame(`<img class="post-detail-cover" src="${plant?'assets/v2/plant-potted.jpg':'assets/v2/hero-wide.jpg'}" alt="${plant?'窗台多肉':'客厅布置'}"><div class="page-pad"><div class="row between"><div class="post-author">${avatar(s)}<strong>${esc(s.name)}</strong></div>${action(WY.state.followed.includes(s.id)?'已关注':'关注','follow','btn secondary compact',{seller:s.id})}</div><h2 class="detail-title">${plant?'给窗台添一点绿，只需要一盆多肉':'不用买全新的，也能住进喜欢的家'}</h2><p class="post-body">${plant?'从附近邻居手里接过这盆小植物，连花盆一起，刚好放在窗边。每天看它一点点生长，也让日常多了一件值得期待的小事。':'搬家的时候没有急着买齐家具。先找一把舒服的椅子，再添一盏暖光灯。很多好物只是暂时闲置，换个地方，依然能好好陪伴生活。'}</p>${heading('文中好物')}${navButton(thumbRow(p),'detail','card related-product',{item:p.id})}${heading('评论')}<div id="comments-list">${(WY.state.comments[route.post||'room']||[]).map(c=>`<div class="comment-row">${avatar('me')}<div><strong>${esc(WY.state.profile.name)}</strong><p>${esc(c.text)}</p></div></div>`).join('')||'<p class="muted">说说你的生活灵感吧。</p>'}</div></div>`,{title:'生活分享',footer:`<form class="chat-inputbar" id="comment-form"><input class="chat-field" aria-label="评论内容" placeholder="写下你的评论…" name="comment" maxlength="300"><button class="text-button" type="submit">发送</button></form>`})}
function topic(){return frame(`<div class="topic-banner"><img src="assets/v2/hero-wide.jpg" alt="客厅"><div><h2 class="topic-title">好物，让家更舒服</h2><p class="topic-copy">一张椅子、一盏灯，慢慢找到家的样子。</p></div></div><div class="page-pad">${heading('家居好物')}${productGrid(WY.search({category:'家居生活'}))}</div>`,{title:'家居生活'})}

function messages(){let conversations=Object.values(WY.state.conversations).sort((a,b)=>(b.updatedAt||0)-(a.updatedAt||0));return frame(`<div class="page-pad"><div class="notification-shortcuts">${[['bell','系统通知','notifications'],['bag','交易消息','transaction-notices']].map(([i,t,to])=>navButton(`<span>${icon(i,23)}</span><strong>${t}</strong>${icon('next',16)}`,to,'notification-shortcut')).join('')}</div><div class="section-heading"><h2>聊天</h2>${action('全部已读','read-all','text-button')}</div><div class="message-list">${conversations.map(c=>{let p=WY.product(c.productId);if(!p)return'';let s=WY.seller(p.sellerId),last=c.messages.at(-1);return navButton(`${avatar(s)}<span class="conversation-main"><span class="row between"><strong class="conversation-name">${esc(s.name)}</strong><time class="message-time">${timeAgo(c.updatedAt||last?.time||Date.now())}</time></span><span class="conversation-preview">${esc(last?.text||'聊聊这件好物吧')}</span></span><span class="conversation-product"><img src="${esc(p.photos[0])}" alt="${esc(p.title)}">${c.unread?`<span class="unread-badge">${c.unread}</span>`:''}</span>`,'chat','conversation-row',{item:p.id})}).join('')||empty('还没有新的消息','去发现一件喜欢的好物，和卖家聊聊吧。')}</div></div>`,{title:'消息',noBack:true,right:navButton(icon('settings'),'settings','icon-button'),tab:'messages'})}
function chat(){let p=currentProduct(),s=WY.seller(p.sellerId),c=WY.conversation(p.id);return frame(`${navButton(`<img src="${esc(p.photos[0])}" alt="${esc(p.title)}"><span class="chat-product-main"><strong>${esc(p.title)}</strong><span class="inline-price">¥${money(p.price)}</span></span><span class="btn primary compact">我想要</span>`,'checkout','chat-product',{item:p.id})}<div class="chat-list"><p class="chat-date">今天</p>${c.messages.map(m=>`<div class="chat-message ${m.role==='me'?'me':''}">${avatar(m.role==='me'?'me':s)}<div class="chat-bubble">${esc(m.text)}</div></div>`).join('')}</div>`,{title:s.name,right:navButton(icon('user'),'seller','icon-button',{seller:s.id}),footer:`<form class="chat-inputbar" id="chat-form">${action(icon('plus',23),'quick-message','icon-button')}<input class="chat-field" name="message" aria-label="聊天消息" placeholder="想问问这件好物…" maxlength="500" autocomplete="off"><button class="icon-button send-button" type="submit" aria-label="发送消息">${icon('send',23)}</button></form>`})}
function notifications(){let trade=route.screen==='transaction-notices';return frame(`<div class="page-pad">${trade?WY.state.orders.map(o=>{let p=WY.product(o.productId);return navButton(`<span class="caption">${timeAgo(o.createdAt)}</span><h2>${esc(o.status)}</h2><p>${esc(p.title)}</p><span class="text-button">查看订单 ${icon('next',16)}</span>`,'order-detail','card notice-card',{order:o.id,item:p.id})}).join('')||empty('还没有交易消息','订单进度会及时通知你。'): `<div class="card notice-card"><p class="caption">今天</p><h2>欢迎来到闲置无忧</h2><p>从一件好物开始，让生活轻一点。</p>${navButton('发现好物 '+icon('next',16),'home','text-button')}</div>`}</div>`,{title:trade?'交易消息':'系统通知'})}

function checkout(){let p=currentProduct(),s=WY.seller(p.sellerId),saved=checkoutDrafts[p.id]||{},delivery=saved.delivery||(p.delivery==='均可'?'同城自提':p.delivery);let address=WY.state.addresses.find(a=>a.id===(saved.addressId||selectedAddress))||WY.state.addresses[0];return frame(`<div class="page-pad"><div class="card"><div class="post-author">${avatar(s)}<strong>${esc(s.name)}</strong></div><div class="divider"></div>${thumbRow(p)}</div><div class="list-group">${action(`<span>交易方式</span><span class="list-trailing">${esc(delivery)} ${p.delivery==='均可'?icon('next',16):''}</span>`,'choose-delivery','list-row',{delivery:p.delivery})}${delivery==='同城自提'?`<div class="list-row"><span class="list-leading">${icon('pin',21)}<span>自提地点</span></span><span class="muted">${esc(p.city)}${esc(p.district)}</span></div><p class="safety-note">下单后和卖家确认详细地点与时间。</p>`:navButton(`<span class="list-leading">${icon('pin',21)}<span>${address?esc(address.name)+' '+esc(address.phone):'添加收货地址'}</span></span><span class="list-trailing">${icon('next',17)}</span>${address?'<span class="address-inline">'+esc(address.region+' '+address.detail)+'</span>':''}`,'address','list-row address-select',{select:'1'})}</div><div class="field"><label class="field-label" for="order-note">给卖家留言</label><input class="input-control text-input" id="order-note" aria-label="订单留言" value="${esc(saved.note||'')}" placeholder="选填，例如方便自提的时间" maxlength="100"></div><div class="card"><div class="summary-row"><span>商品金额</span><span>¥${money(p.price)}</span></div><div class="summary-row"><span>运费</span><span>${delivery==='同城自提'?'无需运费':'卖家包邮'}</span></div><div class="divider"></div><div class="summary-row"><strong>合计</strong><strong class="inline-price">¥${money(p.price)}</strong></div></div></div>`,{title:'确认订单',footer:`<div class="action-bar"><div class="footer-total"><span class="muted">合计</span><strong>¥${money(p.price)}</strong></div>${action('提交订单','create-order','btn primary',{delivery})}</div>`})}
function payment(){let o=currentOrder();if(!o)return frame(empty('订单不存在','返回订单列表看看吧。','我的订单','orders'),{title:'付款'});let p=WY.product(o.productId);return frame(`<div class="page-pad"><div class="payment-total"><span class="muted">需付款</span><strong>¥${money(o.amount)}</strong><span>${esc(p.title)}</span></div><div class="payment-choice"><span class="list-leading">${icon('bag',23)}<strong>订单金额已确认</strong></span>${icon('check',21)}</div><div class="section-heading"><h2>付款方式</h2></div><div class="payment-methods">${['微信支付','支付宝'].map(t=>action(`<span>${t}</span><span class="payment-radio ${paymentMethod===t?'selected':''}">${paymentMethod===t?icon('check',16):''}</span>`,'payment-method','list-row',{value:t})).join('')}</div><p class="safety-note">预览体验，不产生实际扣款。</p></div>`,{title:'付款',footer:`<div class="action-bar">${action('确认付款 ¥'+money(o.amount),'pay','btn primary',{order:o.id})}</div>`})}
function tradeSuccess(){let o=currentOrder(),p=o?WY.product(o.productId):currentProduct();return frame(`<div class="page-pad success-page"><div class="success-icon">${icon('check',40)}</div><h2 class="success-title">付款成功</h2><p class="success-description">${o?.delivery==='同城自提'?'联系卖家，约定方便的自提时间。':'卖家发货后，你可以在订单中查看进度。'}</p><div class="card">${thumbRow(p)}<div class="divider"></div><div class="summary-row"><span>订单状态</span><strong>${esc(o?.status||'待自提')}</strong></div></div>${navButton('查看订单','order-detail','btn primary',{order:o?.id,item:p.id})}${navButton('联系卖家','chat','btn secondary',{item:p.id})}${navButton('继续逛逛','home','text-button')}</div>`,{title:'付款成功',noBack:true})}
function orderCard(o){let p=WY.product(o.productId),s=WY.seller(p.sellerId);return `<article class="card order-card"><div class="row between"><div class="post-author">${avatar(s)}<strong>${esc(s.name)}</strong></div><span class="order-status">${esc(o.status)}</span></div>${navButton(thumbRow(p),'order-detail','order-open',{order:o.id,item:p.id})}<div class="order-footer"><span class="small">合计 <strong>¥${money(o.amount)}</strong></span>${navButton(o.status==='待付款'?'去付款':'查看订单',o.status==='待付款'?'payment':'order-detail',`btn ${o.status==='待付款'?'primary':'secondary'} compact`,{order:o.id,item:p.id})}</div></article>`}
function orders(){let sold=route.mode==='sell',orders=sold?WY.state.orders.filter(o=>WY.product(o.productId)?.sellerId==='me'):WY.state.orders.filter(o=>WY.product(o.productId)?.sellerId!=='me');let visible=orderFilter==='全部'?orders:orders.filter(o=>o.status===orderFilter);return frame(`<div class="page-pad"><div class="order-filter">${['全部','待付款','待自提','待发货','已完成'].map(t=>action(t,'order-filter',`filter-button ${orderFilter===t?'active':''}`,{value:t})).join('')}</div>${visible.map(orderCard).join('')||empty('暂无'+(orderFilter==='全部'?'订单':orderFilter+'订单'),sold?'发布你的第一件闲置，等待新的主人。':'遇到喜欢的好物，就和卖家聊聊吧。',sold?'去发布':'去逛逛',sold?'publish':'home')}</div>`,{title:sold?'我卖出的':'我买到的'})}
function orderDetail(){let o=currentOrder();if(!o)return frame(empty('还没有订单','去挑一件喜欢的好物吧。'),{title:'订单详情'});let p=WY.product(o.productId),s=WY.seller(p.sellerId),copy={'待付款':'请核对物品与交易方式后完成付款。','待自提':'与卖家约定时间，验货满意后再确认收货。','待发货':'卖家发货后，物流信息会在这里更新。','已完成':'谢谢你，让这件好物继续被珍惜。'};return frame(`<div class="page-pad"><div class="receipt-state"><h2>${esc(o.status)}</h2><p>${copy[o.status]||''}</p></div><div class="card"><div class="post-author">${avatar(s)}<strong>${esc(s.name)}</strong></div>${navButton(thumbRow(p),'detail','order-open',{item:p.id})}</div><div class="card"><div class="summary-row"><span>交易方式</span><strong>${esc(o.delivery)}</strong></div><div class="summary-row"><span>订单金额</span><strong>¥${money(o.amount)}</strong></div><div class="summary-row"><span>下单时间</span><span>${new Date(o.createdAt).toLocaleString('zh-CN',{hour12:false})}</span></div><div class="summary-row"><span>订单编号</span><span class="small">${esc(o.id)}</span></div>${o.note?`<div class="divider"></div><p class="muted small">留言：${esc(o.note)}</p>`:''}</div>${listRow('订单遇到问题','chat','help')}</div>`,{title:'订单详情',footer:`<div class="action-bar">${navButton('联系卖家','chat','btn secondary',{item:p.id})}${o.status==='待付款'?navButton('去付款','payment','btn primary',{order:o.id,item:p.id}):['待自提','待收货'].includes(o.status)?action('确认收货','confirm-receive','btn primary',{order:o.id}):navButton('继续逛逛','home','btn primary')}</div>`})}

function profile(){let profile=WY.state.profile,favorites=WY.state.favorites.length,listings=WY.state.listings.length;return frame(`<div class="page-pad"><div class="profile-head">${navButton(`${avatar('me',true)}<span class="profile-main"><strong>${esc(profile.name)}</strong><span>${esc(profile.bio||'让好物继续被珍惜。')}</span></span>${icon('next',19)}`,'edit-profile','profile-main-button')}<div class="profile-stats">${[['我的发布',listings,'my-listings'],['我的收藏',favorites,'favorites'],['浏览记录',WY.state.history.length,'history']].map(([t,n,to])=>navButton(`<strong>${n}</strong><span>${t}</span>`,to,'profile-stat')).join('')}</div></div>${heading('我的交易')}<div class="orders-shortcuts">${[['bag','我买到的','buy'],['box','我卖出的','sell'],['clock','待付款','pending']].map(([i,t,mode])=>navButton(`${icon(i,26)}<span>${t}</span>`,'orders','order-shortcut',{mode})).join('')}</div><div class="list-group">${listRow('收货地址','pin','address')}${listRow('消息通知','bell','notifications')}${listRow('帮助与反馈','chat','help')}</div><div class="list-group">${listRow('账号与设置','settings','settings')}${listRow('关于闲置无忧','leaf','about')}</div></div>`,{title:'我的',noBack:true,right:navButton(icon('settings'),'settings','icon-button'),tab:'profile'})}
function favorites(){let list=WY.state.favorites.map(id=>WY.product(id)).filter(Boolean);return frame(`<div class="page-pad">${list.length?`<div class="result-count">${list.length} 件喜欢的好物</div>`:''}${list.length?productGrid(list):empty('喜欢的好物，先收在这里','看到心仪的物品，点一下心形就能收藏。','去逛逛','home','heart')}</div>`,{title:'我的收藏'})}
function historyPage(){let groups={};WY.state.history.forEach(h=>{let label=timeAgo(h.at);(groups[label]??=[]).push(WY.product(h.id))});return frame(`<div class="page-pad">${Object.entries(groups).map(([day,items])=>heading(day)+productGrid(items.filter(Boolean))).join('')||empty('还没有浏览记录','去看看有没有喜欢的好物。','去逛逛','home','clock')}</div>`,{title:'浏览记录',right:WY.state.history.length?action('清空','clear-history','text-button'):''})}
function myListings(){let list=WY.state.listings.map(id=>typeof id==='object'?id:WY.product(id)).filter(Boolean);return frame(`<div class="page-pad">${list.map(p=>`<article class="card shelf-card">${navButton(thumbRow(p),'detail','order-open',{item:p.id})}<div class="shelf-actions"><span class="small muted">${p.status==='已下架'?'已下架':'在售'}</span>${action('编辑','edit-listing','btn secondary compact',{item:p.id})}${action(p.status==='已下架'?'重新上架':'下架','toggle-listing','text-button',{item:p.id})}</div></article>`).join('')||empty('给闲置一个新的去处','拍下照片，介绍一下它，就能发布。','发布闲置','publish','plus')}</div>`,{title:'我的发布',right:navButton('草稿','draft','text-button')})}
function sellerPage(){let s=currentSeller(),list=WY.search({status:'在售'}).filter(p=>p.sellerId===s.id);return frame(`<div class="page-pad"><div class="seller-profile"><div class="row">${avatar(s,true)}<div><h2 class="page-heading">${esc(s.name)}</h2><p class="muted">${esc(s.city)} · ${esc(s.lastActive||'今天来过')}</p></div></div><p class="post-body">${esc(s.bio)}</p>${action(WY.state.followed.includes(s.id)?'已关注':'关注','follow','btn secondary compact',{seller:s.id})}</div>${heading('TA 的闲置')}${productGrid(list)}</div>`,{title:'卖家主页'})}

function publishPage(preview=false){let d=WY.state.draft;if(preview){let p={id:'draft',title:d.title||'你的闲置物品',description:d.description,price:d.price,photos:d.photos.length?d.photos:['assets/chair.jpg'],condition:d.condition,delivery:d.delivery};return frame(`<img class="detail-photo" src="${esc(p.photos[0])}" alt="物品照片"><div class="page-pad"><div class="detail-price">¥${money(p.price)}</div><h2 class="detail-title">${esc(p.title)}</h2><p class="detail-summary">${esc(d.condition)} · ${esc(d.category)} · ${esc(deliveryText(d.delivery))}</p><p class="detail-description">${esc(d.description)}</p></div>`,{title:'发布预览',footer:`<div class="action-bar">${navButton('继续编辑','publish','btn secondary',draftEditingId?{item:draftEditingId,edit:'1'}:{})}${action(draftEditingId?'保存修改':'确认发布','publish-submit','btn primary')}</div>`})}return frame(`<div class="page-pad publish-form"><div class="upload-grid">${d.photos.map((src,i)=>`<div class="upload-photo"><img src="${esc(src)}" alt="物品照片 ${i+1}">${action(icon('close',16),'remove-photo','upload-remove',{index:i})}</div>`).join('')}${d.photos.length<9?`<label class="upload-tile" for="photo-upload">${icon('camera',28)}<span>添加照片</span><span class="caption">${d.photos.length}/9</span></label><input id="photo-upload" type="file" accept="image/*" multiple hidden>`:''}</div><div class="field"><label class="field-label" for="publish-title">物品名称</label><input class="input-control text-input" id="publish-title" aria-label="物品名称" name="title" placeholder="例如：搬家转让布艺休闲椅" maxlength="30" value="${esc(d.title)}"></div><div class="field"><label class="field-label" for="publish-desc">物品描述</label><textarea class="textarea-input" id="publish-desc" aria-label="物品描述" name="description" placeholder="介绍成色、使用情况和转让原因，如有瑕疵请如实说明。" maxlength="500">${esc(d.description)}</textarea></div><div class="publish-properties"><div class="field"><label class="field-label" for="publish-price">出售价格</label><div class="input-shell"><span class="currency">¥</span><input class="input-control price-input" id="publish-price" name="price" aria-label="出售价格" type="number" min="0.01" max="999999" step="0.01" placeholder="0.00" value="${esc(d.price||'')}"></div></div><div class="field"><label class="field-label" for="publish-category">分类</label><select class="input-control form-select" id="publish-category" name="category" aria-label="分类"><option value="">选择分类</option>${categories.slice(1).map(([,t])=>`<option ${d.category===t?'selected':''}>${t}</option>`).join('')}</select></div><div class="field"><label class="field-label" for="publish-condition">成色</label><select class="input-control form-select" id="publish-condition" name="condition" aria-label="成色"><option value="">选择成色</option>${['近全新','九成新','有使用痕迹'].map(t=>`<option ${d.condition===t?'selected':''}>${t}</option>`).join('')}</select></div><div class="field"><label class="field-label" for="publish-delivery">交易方式</label><select class="input-control form-select" id="publish-delivery" name="delivery" aria-label="交易方式"><option value="">选择交易方式</option>${['同城自提','快递邮寄','均可'].map(t=>`<option ${d.delivery===t?'selected':''}>${t}</option>`).join('')}</select></div></div><div class="row muted small">${icon('pin',18)}${esc(WY.state.city)}<span class="grow"></span>${navButton('修改','location','text-button',{return:'publish'})}</div><p class="form-error" id="publish-error" role="alert"></p></div>`,{title:draftEditingId?'编辑闲置':'发布闲置',right:action('保存草稿','save-draft','text-button'),footer:`<div class="action-bar">${action('预览并发布','publish-preview','btn primary')}</div>`})}
function publishSuccess(){let edited=route.mode==='edited';let p=WY.product(publishedId||route.item)?.sellerId==='me'?WY.product(publishedId||route.item):WY.products().find(p=>p.sellerId==='me')||currentProduct();return frame(`<div class="page-pad success-page"><div class="success-icon">${icon('check',40)}</div><h2 class="success-title">${edited?'修改已保存':'发布成功'}</h2><p class="success-description">${edited?'物品信息已更新。':'好物已经上架，等待新的主人。'}</p><div class="card">${thumbRow(p)}</div>${navButton('查看我的发布','my-listings','btn primary')}${navButton('再发一件','publish','btn secondary')}${navButton('回到首页','home','text-button')}</div>`,{title:'发布成功',noBack:true})}
function draftPage(){let d=WY.state.draft;return frame(`<div class="page-pad">${d.title||d.photos.length?`<article class="card"><div class="order-product"><img class="order-image" src="${esc(d.photos[0]||'assets/logo.svg')}" alt="草稿"><div><h3 class="order-title">${esc(d.title||'未命名的闲置')}</h3><p class="muted">${d.price?'¥'+money(d.price):'尚未填写价格'}</p></div></div>${navButton('继续编辑','publish','btn primary compact')}</article>`:empty('还没有草稿','尚未发布的物品会保存在这里。','发布闲置','publish','plus')}</div>`,{title:'我的草稿'})}

function authPage(){let id=route.screen,reg=id.startsWith('register'),sms=id==='login-sms',code=id==='login-code',reset=id==='reset',error=id.includes('error')?'手机号或密码不正确，请重新输入。':accountError;return frame(`<div class="page-pad auth-page"><div class="auth-logo">${logo(52)}</div><h2 class="auth-title">${reg?'注册闲置无忧':reset?'重设密码':code?'输入验证码':'欢迎回来'}</h2><p class="auth-subtitle">${reg?'让闲置遇见新的主人。':reset?'验证手机号后，设置新的登录密码。':code?'验证码已发送至 '+esc(accountForm.phone.slice(0,3)||'138')+' **** '+esc(accountForm.phone.slice(-4)||'8000'):'登录后，收藏、发布和沟通都在这里。'}</p><form id="account-form">${!code?formField('手机号码','phone','输入 11 位手机号码','tel',accountForm.phone,'inputmode="numeric" maxlength="11" autocomplete="tel"'):''}${reg||reset||code?`<div class="field"><label class="field-label" for="auth-code">验证码</label><div class="input-shell"><input class="input-control" id="auth-code" name="code" aria-label="验证码" placeholder="输入 6 位验证码" maxlength="6" inputmode="numeric" value="${esc(accountForm.code)}">${action(smsUntil>Date.now()?Math.ceil((smsUntil-Date.now())/1000)+' 秒后重发':'获取验证码','sms','code-button')}</div></div>`:''}${!sms&&!code?formField(reset||reg?'设置密码':'密码','password',reset||reg?'8–20 位，包含字母和数字':'输入密码','password',accountForm.password,'autocomplete="off"'):''}${!code?`<label class="agreement"><input name="consent" type="checkbox" ${accountForm.consent?'checked':''}><span>我已阅读并同意 ${navButton('用户协议','terms','text-button')}与${navButton('隐私政策','privacy','text-button')}</span></label>`:''}<p class="form-error" role="alert">${esc(error)}</p><button class="btn primary" id="account-submit" type="submit" ${accountReady()?'':'disabled'}>${accountBusy?'正在处理…':reg?'注册':reset?'确认重设':sms?'获取验证码':code?'验证并登录':'登录'}</button></form>${!reg&&!reset&&!code?`<div class="auth-switch row between">${navButton(sms?'密码登录':'短信登录',sms?'login':'login-sms','text-button')}${navButton('忘记密码','reset','text-button')}</div>`:''}${!reset&&!code?`<p class="auth-switch">${reg?'已有账号？':'还没有账号？'}${navButton(reg?'登录':'立即注册',reg?'login':'register','text-button')}</p>`:''}</div>`,{title:'',right:navButton('先逛逛','home','text-button')})}
function accountReady(){if(accountBusy)return false;let id=route.screen,reg=id.startsWith('register'),reset=id==='reset',sms=id==='login-sms',code=id==='login-code';if(code)return /^\d{6}$/.test(accountForm.code);return /^1\d{10}$/.test(accountForm.phone)&&accountForm.consent&&(sms||/^(?=.*[A-Za-z])(?=.*\d).{8,20}$/.test(accountForm.password))&&(!(reg||reset)||/^\d{6}$/.test(accountForm.code))}
function onboarding(){let n=Math.min(3,Math.max(1,Number(route.screen.at(-1))||1)),data=[['闲置好物<br>值得再被喜欢','找到需要的人，让物品继续陪伴生活。','assets/v2/hero-wide.jpg'],['轻松发布<br>让闲置有去处','拍下照片，如实介绍，等待新的主人。','assets/chair.jpg'],['先聊清楚<br>再放心交易','沟通物品情况，确认每一步交易进度。','assets/v2/plant-potted.jpg']][n-1];return frame(`<div class="onboarding"><div class="onboard-art">${n===3?`<div class="onboard-trust"><span class="trust-orbit"></span><div class="trust-shield">${icon('shield',128)}</div><span class="trust-avatar trust-avatar-left">${avatar('mumu')}</span><span class="trust-avatar trust-avatar-right">${avatar('me')}</span></div>`:`<img class="onboard-photo" src="${data[2]}" alt="${data[0].replace(/<br>/g,'，')}"><div class="onboard-logo">${n===2?icon('camera',28):logo(64)}</div>`}</div><h2 class="onboard-title">${data[0]}</h2><p class="onboard-text">${data[1]}</p><div class="onboard-bottom"><div class="onboard-dots">${[1,2,3].map(i=>`<span class="${i===n?'active':''}"></span>`).join('')}</div>${navButton(n===3?'开始使用':'下一步',n===3?'login':'onboard'+(n+1),'btn primary')}</div></div>`,{title:'',noBack:true,right:navButton('跳过','home','text-button')})}

function addressPage(){let selecting=route.select==='1';return frame(`<div class="page-pad">${WY.state.addresses.map(a=>`<article class="card address-card">${selecting?action(`<strong class="address-name">${esc(a.name)} <span>${esc(a.phone)}</span></strong><p class="address-detail">${esc(a.region)} ${esc(a.detail)}</p>`,'select-address','address-open',{address:a.id}):`<strong class="address-name">${esc(a.name)} <span>${esc(a.phone)}</span></strong><p class="address-detail">${esc(a.region)} ${esc(a.detail)}</p>`}<div class="row between"><span class="small muted">${a.isDefault?'默认地址':''}</span>${navButton('编辑','edit-address','text-button',{address:a.id,select:route.select||''})}</div></article>`).join('')||empty('还没有收货地址','邮寄好物时，添加一个方便收件的地址。','','home','pin')}</div>`,{title:'收货地址',footer:`<div class="action-bar">${navButton('新增收货地址','edit-address','btn primary',{select:route.select||''})}</div>`})}
function editAddress(){let a=WY.state.addresses.find(a=>a.id===route.address)||{};return frame(`<form class="page-pad" id="address-form">${formField('收件人','name','姓名','text',a.name||'','maxlength="20"')}${formField('手机号码','phone','11 位手机号','tel',a.phone||'','maxlength="11"')}${formField('省市区','region','例如：浙江省 杭州市 西湖区','text',a.region||'')}${formField('详细地址','detail','街道、小区、楼栋和门牌号','text',a.detail||'')}<label class="list-row"><span>设为默认地址</span><input class="check-control" type="checkbox" name="isDefault" ${a.isDefault?'checked':''}></label><p id="address-error" class="form-error" role="alert"></p></form>`,{title:a.id?'编辑地址':'新增地址',footer:`<div class="action-bar"><button class="btn primary" form="address-form" type="submit">保存地址</button></div>`})}
function editProfile(){let p=WY.state.profile;return frame(`<form class="page-pad" id="profile-form"><div class="profile-edit-avatar">${avatar('me',true)}</div>${formField('昵称','name','2–12 个字符','text',p.name,'maxlength="12"')}${formField('个人简介','bio','介绍一下自己','text',p.bio||'','maxlength="50"')}<p class="form-error" id="profile-error" role="alert"></p></form>`,{title:'编辑资料',footer:`<div class="action-bar"><button class="btn primary" form="profile-form" type="submit">保存</button></div>`})}
function settings(){return frame(`<div class="page-pad"><div class="list-group">${listRow('编辑资料','user','edit-profile')}${listRow('账号与安全','lock','security')}${listRow('收货地址','pin','address')}</div><div class="list-group"><div class="list-row"><span class="list-leading">${icon('bell',21)}消息通知</span>${action('','notification-switch',`switch ${WY.state.notificationEnabled?'':'off'}`)}</div>${listRow('隐私政策','shield','privacy')}${listRow('帮助与反馈','chat','help')}${listRow('关于闲置无忧','leaf','about')}</div>${action('退出登录','logout','btn secondary settings-logout')}</div>`,{title:'设置'})}
function help(){return frame(`<div class="page-pad">${heading('常见问题')}${[['如何发布闲置？','在发布页添加真实照片，填写名称、价格与物品情况，预览确认后发布。'],['同城自提如何安排？','先在聊天中和卖家确认时间、地点。建议在公共场所见面，验货满意后再确认收货。'],['如何修改已发布的物品？','进入“我的发布”，点击物品下方的编辑；也可以暂时下架。']].map(([q,a])=>`<details class="help-details"><summary>${q}${icon('next',16)}</summary><p>${a}</p></details>`).join('')}${heading('意见反馈')}<form id="feedback-form"><textarea class="textarea-input" aria-label="意见反馈" name="feedback" placeholder="告诉我们遇到的问题或建议" maxlength="500"></textarea><p class="field-error" id="feedback-error"></p><button class="btn primary" type="submit">提交反馈</button></form></div>`,{title:'帮助与反馈'})}
function legal(){let privacy=route.screen==='privacy';return frame(`<div class="page-pad legal-page"><h2>${privacy?'你的信息，由你掌握':'让每一次交易都清楚'}</h2><p>${privacy?'我们只在当前浏览器保存收藏、浏览记录和填写的资料。照片用于展示你发布的物品，消息用于与卖家沟通。':'请如实介绍物品成色、功能和瑕疵，使用自己的照片，避免发布侵权或禁止交易的物品。'}</p><h3>${privacy?'管理个人资料':'沟通与履约'}</h3><p>${privacy?'你可以在个人资料、地址和收藏页面修改已保存的信息。请勿在公开描述中提供身份证、银行卡或验证码。':'下单前核对物品描述、价格与交付方式。当面交易时先验货，再确认收货；有问题可以通过帮助与反馈联系处理。'}</p><h3>${privacy?'本地数据':'预览范围'}</h3><p>${privacy?'清除浏览器站点数据会删除本地保存的内容。当前预览没有接入账号服务器。':'当前版本用于体验界面和本地流程，不产生真实付款、发货或线上商品发布。'}</p></div>`,{title:privacy?'隐私政策':'用户协议'})}
function about(){return frame(`<div class="page-pad about-page">${logo(80)}<h2>闲置无忧</h2><p>让闲置遇见新的喜欢。</p><p class="muted">买卖闲置，分享生活。<br>把用得上的好物，交给正需要的人。</p>${navButton('查看新手引导','onboard1','btn secondary')}${navButton('用户协议','terms','text-button')}${navButton('隐私政策','privacy','text-button')}</div>`,{title:'关于闲置无忧'})}
function security(){return frame(`<div class="page-pad"><div class="list-group">${listRow('重设密码','lock','reset')}</div><p class="muted small">请妥善保护账号信息，勿向他人提供验证码。</p></div>`,{title:'账号与安全'})}
function locationPage(){return frame(`<div class="page-pad">${heading('当前城市')}<div class="card current-city">${icon('pin',21)}<strong>${esc(WY.state.city)}</strong></div>${heading('选择城市')}<div class="choice-grid">${['杭州','上海','北京','广州','深圳','成都'].map(t=>action(t,'city',`choice-button ${WY.state.city===t?'selected':''}`,{value:t})).join('')}</div></div>`,{title:'选择城市'})}

const renderers={home,search:searchPage,results,category:results,nearby:results,categories:categoriesPage,detail,discover,topic,post,messages,chat,notifications,'transaction-notices':notifications,checkout,payment,'trade-success':tradeSuccess,orders,'order-detail':orderDetail,profile,favorites,history:historyPage,'my-listings':myListings,seller:sellerPage,publish:()=>publishPage(false),'publish-preview':()=>publishPage(true),'publish-success':publishSuccess,draft:draftPage,login:authPage,register:authPage,reset:authPage,'login-code':authPage,'login-sms':authPage,'login-error':authPage,'register-error':authPage,address:addressPage,'edit-address':editAddress,'edit-profile':editProfile,settings,help,privacy:legal,terms:legal,about,security,location:locationPage,onboard1:onboarding,onboard2:onboarding,onboard3:onboarding,empty:()=>frame(empty('还没有新的消息','去发现一件喜欢的好物，和卖家聊聊吧。'),{title:'消息',noBack:true,tab:'messages'})};
const titles={home:'首页',discover:'逛逛',publish:'发布闲置',messages:'消息',profile:'我的',detail:'商品详情',chat:'聊天',checkout:'确认订单',payment:'付款',orders:'我的订单','order-detail':'订单详情',favorites:'我的收藏','my-listings':'我的发布',search:'搜索',results:'搜索结果',category:'分类',nearby:'附近',settings:'设置',login:'登录',register:'注册',onboard1:'引导一',onboard2:'引导二',onboard3:'引导三','publish-preview':'发布预览','publish-success':'发布成功','trade-success':'付款成功'};
function routeKey(r=route){return JSON.stringify(r)}
function captureDraft(){if(route.screen!=='publish'||reviewMode)return;let form=root.querySelector('.publish-form');if(!form)return;let update={};form.querySelectorAll('input[name],select[name],textarea[name]').forEach(e=>update[e.name]=e.value);WY.updateDraft(update)}
function captureCheckout(){if(route.screen!=='checkout')return;let input=document.getElementById('order-note');if(input){checkoutDrafts[route.item]={...checkoutDrafts[route.item],note:input.value}}}
function navigate(screen,data={},replace=false){captureCheckout();if(screen==='publish'&&data.edit!=='1')draftEditingId='';if(!WY.state.loggedIn&&['publish','chat','checkout'].includes(screen)){pendingRoute={screen,data};screen='login';data={}}captureDraft();let body=root.querySelector('.screen-body');if(body)screenScroll.set(routeKey(),body.scrollTop);if(!replace)backStack.push({...route});let next={screen,item:data.item||route.item||'chair-01'};for(let [k,v]of Object.entries(data))if(!['go','action','screen'].includes(k))next[k]=v;if(['detail','chat','checkout'].includes(screen)){WY.visit(next.item)}if(screen==='orders'){orderFilter=data.mode==='pending'?'待付款':'全部';next.mode=data.mode==='pending'?'buy':data.mode||'buy'}if(['results','search'].includes(screen)&&data.query===undefined)next.query=route.query||'';if(['category','nearby','results'].includes(screen)&&route.screen!==screen){filters={};searchSort='综合'}route=next;const q=new URLSearchParams();if(screen!=='home')q.set('screen',screen);for(let k of ['item','category','query','order','seller','post','mode','select','address','return','edit'])if(route[k])q.set(k,route[k]);history[replace?'replaceState':'pushState'](route,'',location.pathname+(q.size?'?'+q.toString():''));render();}
function goBack(){captureCheckout();captureDraft();if(backStack.length){route=backStack.pop();let q=new URLSearchParams(route);history.replaceState(route,'',location.pathname+'?'+q.toString());render();let body=root.querySelector('.screen-body');if(body)body.scrollTop=screenScroll.get(routeKey())||0}else navigate(mainScreens.includes(route.screen)?'home':fallbackBack(route.screen),{},true)}
function fallbackBack(s){return ['orders','settings','favorites','history','my-listings','address','edit-profile','help'].includes(s)?'profile':['login','register','reset','onboard1','onboard2','onboard3'].includes(s)?'home':['checkout','seller'].includes(s)?'detail':s==='order-detail'?'orders':'home'}
function render(){if(reviewMode)return renderReview();if(route.edit==='1'&&WY.product(route.item)?.sellerId==='me')draftEditingId=route.item;if(['detail','chat','checkout','seller'].includes(route.screen)&&!WY.product(route.item)){root.innerHTML=`<div class="app-stage">${frame(empty('这件物品已不在了','返回首页，看看其他值得喜欢的好物。'),{title:'商品'})}</div>`;return}const fn=renderers[route.screen]||home;root.innerHTML=`<div class="app-stage">${fn()}</div>`;document.title=(titles[route.screen]||'闲置无忧')+' · 闲置无忧';hydrate();}
function hydrate(){if(accountError||route.screen.includes('error')){let form=document.getElementById('account-form');if(form){let names=['register','reset','login-code'].includes(route.screen)?['code']:['phone','password'];for(let name of names){let input=form.elements[name];input?.closest('.input-shell')?.classList.add('error');input?.setAttribute('aria-invalid','true')}}}if(route.screen==='chat'){let c=WY.conversation(currentProduct().id);if(c)c.unread=0;WY.save();let body=root.querySelector('.screen-body');body.scrollTop=body.scrollHeight}if(route.screen==='login-code'&&smsUntil>Date.now())updateSms();if(route.screen==='publish'){let input=document.getElementById('photo-upload');input?.addEventListener('change',uploadPhotos)}}
function toast(text){let container=document.getElementById('toast-root');if(!container)return;container.innerHTML=`<div class="toast" role="status">${esc(text)}</div>`;setTimeout(()=>{container.innerHTML=''},2400)}
function sheet(title,content,footer=''){let el=document.getElementById('overlay-root');el.innerHTML=`<div class="sheet-backdrop"><section class="sheet" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="sheet-handle"></div><div class="row between"><h2 class="sheet-title">${esc(title)}</h2>${action(icon('close',22),'close-sheet','icon-button')}</div>${content}${footer?`<div class="sheet-actions">${footer}</div>`:''}</section></div>`}
function closeSheet(){document.getElementById('overlay-root').innerHTML=''}
function filterSheet(){sheet('筛选',`<div class="filters-fields"><label class="field-label">价格区间</label><div class="price-range-fields"><input class="input-control text-input" aria-label="最低价格" type="number" min="0" id="filter-min" value="${esc(filters.min??'')}" placeholder="最低价"><span>—</span><input class="input-control text-input" aria-label="最高价格" type="number" min="0" id="filter-max" value="${esc(filters.max??'')}" placeholder="最高价"></div><label class="field-label">成色</label><div class="choice-grid" data-filter="condition">${['不限','近全新','九成新','有使用痕迹'].map(t=>action(t,'filter-choice',`choice-button ${(filters.condition||'不限')===t?'selected':''}`,{value:t})).join('')}</div><label class="field-label">交易方式</label><div class="choice-grid" data-filter="delivery">${['不限','同城自提','快递邮寄'].map(t=>action(t,'filter-choice',`choice-button ${(filters.delivery||'不限')===t?'selected':''}`,{value:t})).join('')}</div><p id="filter-error" class="form-error"></p></div>`,action('重置','reset-filter','btn secondary')+action('查看结果','apply-filter','btn primary'))}
function confirmReceipt(orderId){sheet('确认已收到物品？','<p class="post-body">请先核对物品成色与功能，确认与描述一致后，再完成订单。</p>',action('再检查一下','close-sheet','btn secondary')+action('确认收货','receive','btn primary',{order:orderId}))}
function updateSms(){clearInterval(timer);timer=setInterval(()=>{let b=root.querySelector('[data-action="sms"]');if(!b){clearInterval(timer);return}let n=Math.max(0,Math.ceil((smsUntil-Date.now())/1000));b.disabled=n>0;b.textContent=n?`${n} 秒后重发`:'重新获取';if(!n)clearInterval(timer)},500)}
function renderReview(){let groups={overview:['home','discover','publish','messages','profile'],onboard:['onboard1','onboard2','onboard3'],auth:['login','register','login-code'],trade:['detail','chat','checkout','payment','trade-success'],account:['profile','orders','favorites','my-listings','settings'],publish:['publish','publish-preview','publish-success']};let group=urlParams.get('board')||'overview',ids=groups[group]||Object.keys(renderers);let saved=route;document.body.classList.add('review-mode');root.innerHTML=`<div class="review-grid">${ids.map(id=>{route={...saved,screen:id};return `<section class="review-frame"><h2 class="review-name">${esc(titles[id]||id)}</h2>${(renderers[id]||home)()}</section>`}).join('')}</div>`;route=saved;}

document.addEventListener('click',e=>{let button=e.target.closest('button');if(!button||button.disabled)return;let to=button.dataset.go;if(to){let data={...button.dataset};delete data.go;if(to==='detail'&&data.item)WY.visit(data.item);if(to==='publish'&&data.item){let p=WY.product(data.item);if(p?.sellerId==='me'){draftEditingId=p.id;data.edit='1';WY.updateDraft({...p,photos:[...p.photos]})}}navigate(to,data);return}let type=button.dataset.action;if(!type)return;let d=button.dataset,p;
switch(type){
case 'back':goBack();break;
case 'home-feed':homeFeed=d.value;render();break;
case 'sort':searchSort=d.value;render();break;
case 'filters':filterSheet();break;
case 'filter-choice':button.parentElement.querySelectorAll('button').forEach(b=>b.classList.toggle('selected',b===button));break;
case 'close-sheet':closeSheet();break;
case 'apply-filter':{let min=document.getElementById('filter-min').value,max=document.getElementById('filter-max').value;if((min&&+min<0)||(max&&+max<0)||(min&&max&&+min>+max)){document.getElementById('filter-error').textContent='请输入有效的价格区间';break}filters={};if(min)filters.min=+min;if(max)filters.max=+max;document.querySelectorAll('[data-filter]').forEach(g=>{let v=g.querySelector('.selected')?.dataset.value;if(v&&v!=='不限')filters[g.dataset.filter]=v});render();break}
case 'reset-filter':filters={};filterSheet();break;
case 'clear-filters':filters={};render();break;
case 'favorite':{let y=root.querySelector('.screen-body')?.scrollTop||0;WY.favorite(d.item||route.item);render();if(root.querySelector('.screen-body'))root.querySelector('.screen-body').scrollTop=y;break}
case 'clear-search':localStorage.removeItem('xzw-v2-searches');render();break;
case 'clear-history':sheet('清空浏览记录？','<p class="post-body">清空后，你可以继续浏览并保存新的记录。</p>',action('取消','close-sheet','btn secondary')+action('清空','do-clear-history','btn primary'));break;
case 'do-clear-history':WY.state.history=[];WY.save();render();break;
case 'discover-feed':discoverFeed=d.value;render();break;
case 'like':{let id=d.post||route.post||'room';WY.state.likes=WY.state.likes.includes(id)?WY.state.likes.filter(x=>x!==id):[...WY.state.likes,id];WY.save();render();break}
case 'follow':{let id=d.seller;WY.state.followed=WY.state.followed.includes(id)?WY.state.followed.filter(x=>x!==id):[...WY.state.followed,id];WY.save();render();break}
case 'read-all':Object.values(WY.state.conversations).forEach(c=>c.unread=0);WY.save();render();break;
case 'quick-message':sheet('想了解些什么？',`<div class="quick-messages">${['你好，这件物品还在吗？','方便拍一下细节和使用痕迹吗？','请问什么时候方便交易？'].map(t=>action(esc(t),'quick-send','list-row',{text:t})).join('')}</div>`);break;
case 'quick-send':WY.send(currentProduct().id,d.text);render();break;
case 'choose-delivery':if(d.delivery==='均可')sheet('交易方式',`<div class="choice-grid">${['同城自提','快递邮寄'].map(t=>action(t,'set-delivery','choice-button',{value:t})).join('')}</div>`);break;
case 'set-delivery':captureCheckout();checkoutDrafts[route.item]={...checkoutDrafts[route.item],delivery:d.value};render();break;
case 'create-order':{p=currentProduct();let delivery=d.delivery,address=WY.state.addresses.find(a=>a.id===(checkoutDrafts[p.id]?.addressId||selectedAddress))||WY.state.addresses[0];if(delivery==='快递邮寄'&&!address){toast('请先添加收货地址');break}let o=WY.createOrder(p.id,{delivery,note:document.getElementById('order-note').value.trim(),addressId:address?.id});if(!o){toast('这件物品暂时无法下单');break}navigate(o.status==='待付款'?'payment':'order-detail',{item:p.id,order:o.id});break}
case 'payment-method':paymentMethod=d.value;render();break;
case 'pay':if(currentOrder()?.status!=='待付款'){navigate('order-detail',{order:d.order,item:route.item});break}button.disabled=true;button.innerHTML='<span class="loading-spinner"></span>正在处理';setTimeout(()=>{WY.payOrder(d.order);navigate('trade-success',{item:route.item,order:d.order})},650);break;
case 'order-filter':orderFilter=d.value;render();break;
case 'confirm-receive':confirmReceipt(d.order);break;
case 'receive':WY.completeOrder(d.order);closeSheet();render();toast('订单已完成');break;
case 'select-address':selectedAddress=d.address;checkoutDrafts[route.item]={...checkoutDrafts[route.item],addressId:d.address};navigate('checkout',{item:route.item},true);break;
case 'notification-switch':WY.state.notificationEnabled=!WY.state.notificationEnabled;WY.save();render();break;
case 'city':WY.setCity(d.value);if(backStack.at(-1)?.screen==='publish'){goBack()}else navigate('home');break;
case 'eye':{let input=button.parentElement.querySelector('input');input.type=input.type==='password'?'text':'password';button.setAttribute('aria-label',input.type==='password'?'显示密码':'隐藏密码');break}
case 'sms':captureAccount();if(!/^1\d{10}$/.test(accountForm.phone)){accountError='请先输入有效的手机号码';render();break}smsUntil=Date.now()+60000;updateSms();button.disabled=true;button.textContent='60 秒后重发';toast('验证码已发送');break;
case 'logout':sheet('退出登录？','<p class="post-body">退出后仍可浏览好物。</p>',action('取消','close-sheet','btn secondary')+action('退出登录','do-logout','btn primary'));break;
case 'do-logout':WY.state.loggedIn=false;WY.save();navigate('login');break;
case 'save-draft':captureDraft();toast('草稿已保存');break;
case 'remove-photo':captureDraft();WY.updateDraft({photos:WY.state.draft.photos.filter((_,i)=>i!==+d.index)});render();break;
case 'publish-preview':{captureDraft();let x=WY.state.draft,error=!x.photos.length?'请添加至少一张物品照片':!x.title.trim()?'请填写物品名称':!x.description.trim()?'请介绍物品情况':!x.price||+x.price<=0||+x.price>999999?'请填写有效价格':!x.category?'请选择分类':!x.condition?'请选择成色':!x.delivery?'请选择交易方式':'';if(error){document.getElementById('publish-error').textContent=error;document.getElementById('publish-error').scrollIntoView({block:'nearest'});break}navigate('publish-preview',{edit:draftEditingId?'1':''});break}
case 'publish-submit':button.disabled=true;button.textContent='正在保存…';setTimeout(()=>{let edited=!!draftEditingId;if(draftEditingId){let item=WY.product(draftEditingId);WY.updateListing(item.id,WY.state.draft);publishedId=item.id;draftEditingId=''}else{publishedId=WY.publish(WY.state.draft).id}WY.updateDraft(WY.defaultDraft());navigate('publish-success',{item:publishedId,mode:edited?'edited':''})},650);break;
case 'edit-listing':{p=WY.product(d.item);draftEditingId=p.id;WY.updateDraft({...p,photos:[...p.photos]});navigate('publish',{item:p.id,edit:'1'});break}
case 'toggle-listing':{p=WY.product(d.item);p.status=p.status==='已下架'?'在售':'已下架';WY.save();render();break}
}
});
function captureAccount(){let f=document.getElementById('account-form');if(!f)return;for(let n of ['phone','password','code'])if(f.elements[n])accountForm[n]=f.elements[n].value;accountForm.consent=!!f.elements.consent?.checked;}
document.addEventListener('input',e=>{if(e.target.closest('#account-form')){captureAccount();accountError='';let b=document.getElementById('account-submit');if(b)b.disabled=!accountReady();let error=root.querySelector('.form-error');if(error)error.textContent='';root.querySelectorAll('.input-shell.error').forEach(el=>el.classList.remove('error'));root.querySelectorAll('[aria-invalid]').forEach(el=>el.removeAttribute('aria-invalid'))}if(e.target.closest('.publish-form'))captureDraft()});
document.addEventListener('change',e=>{if(e.target.closest('#account-form')){captureAccount();document.getElementById('account-submit').disabled=!accountReady()}if(e.target.closest('.publish-form'))captureDraft()});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&document.querySelector('.sheet-backdrop'))closeSheet()});
document.addEventListener('submit',e=>{let f=e.target;e.preventDefault();let data=new FormData(f);if(f.id==='search-form'){navigate('results',{query:String(data.get('query')||'').trim()});return}if(f.id==='chat-form'){let msg=String(data.get('message')||'').trim();if(msg){WY.send(currentProduct().id,msg);render()}return}if(f.id==='comment-form'){let text=String(data.get('comment')||'').trim();if(!text)return;let id=route.post||'room';(WY.state.comments[id]??=[]).push({text,time:Date.now()});WY.save();render();return}if(f.id==='account-form'){captureAccount();if(!accountReady())return;let id=route.screen;if(id==='login-sms'){smsUntil=Date.now()+60000;navigate('login-code');return}if((id==='register'||id==='reset'||id==='login-code')&&accountForm.code!=='123456'){accountError='验证码不正确，请重新输入';render();return}if(id==='login'&&accountForm.password!=='wuyou123'){accountError='手机号或密码不正确，请重新输入';render();return}accountBusy=true;render();setTimeout(()=>{accountBusy=false;accountError='';WY.state.loggedIn=true;WY.save();accountForm.password='';if(id==='reset'){navigate('login');toast('密码已重设')}else if(pendingRoute){let target=pendingRoute;pendingRoute=null;navigate(target.screen,target.data)}else navigate('home')},650);return}if(f.id==='address-form'){let x=Object.fromEntries(data);x.isDefault=data.has('isDefault');let err=!x.name.trim()?'请填写收件人姓名':!/^1\d{10}$/.test(x.phone)?'请填写有效的手机号码':!x.region.trim()||!x.detail.trim()?'请填写完整地址':'';if(err){document.getElementById('address-error').textContent=err;return}if(route.address)x.id=route.address;WY.addAddress(x);navigate('address',{select:route.select||'',item:route.item},true);toast('地址已保存');return}if(f.id==='profile-form'){let x=Object.fromEntries(data);if(x.name.trim().length<2){document.getElementById('profile-error').textContent='昵称至少需要 2 个字符';return}WY.updateProfile(x);navigate('profile');toast('资料已保存');return}if(f.id==='feedback-form'){let text=String(data.get('feedback')||'').trim();if(!text){document.getElementById('feedback-error').textContent='请先填写反馈内容';return}let feedbacks=JSON.parse(localStorage.getItem('xzw-v2-feedback')||'[]');feedbacks.push({text,time:Date.now()});localStorage.setItem('xzw-v2-feedback',JSON.stringify(feedbacks));f.reset();toast('反馈已保存');}});
async function uploadPhotos(event){let files=[...event.target.files].filter(f=>f.type.startsWith('image/')).slice(0,9-WY.state.draft.photos.length);if(!files.length)return;try{let photos=await Promise.all(files.map(file=>new Promise((resolve,reject)=>{let fr=new FileReader();fr.onerror=reject;fr.onload=()=>{let img=new Image();img.onerror=reject;img.onload=()=>{let canvas=document.createElement('canvas'),scale=Math.min(1,1200/Math.max(img.width,img.height));canvas.width=Math.round(img.width*scale);canvas.height=Math.round(img.height*scale);canvas.getContext('2d').drawImage(img,0,0,canvas.width,canvas.height);resolve(canvas.toDataURL('image/jpeg',.82))};img.src=fr.result};fr.readAsDataURL(file)})));captureDraft();WY.updateDraft({photos:[...WY.state.draft.photos,...photos]});render()}catch{toast('照片暂时无法读取，请换一张试试')}}
window.addEventListener('popstate',e=>{captureCheckout();captureDraft();let params=new URLSearchParams(location.search);route=e.state||Object.fromEntries(params);route.screen=route.screen||'home';route.item=route.item||'chair-01';render()});
window.WYApp={render,navigate,get route(){return route},screens:Object.keys(renderers)};
render();
